const bar = ([text, small]: string[]): Block => (small ? { t: "bar", text, small } : { t: "bar", text });
const text = (html: string): Block => ({ t: "text", html });
const ul = (a: string[]) => "<ul>" + a.map((x) => `<li>${x}</li>`).join("") + "</ul>";
const col = (secs: [string, string[]][]) => secs.map(([h, items]) => `<p>${h}</p>${ul(items)}`).join("");

/** Texts the renderer prints itself (copied from the old pages). */
export const PAGE_TEXT = {
  dose: T.dose, goal: T.cover_goal, sign: T.sign, trRows: T.tr_rows as string[], wu: T.x_wu as string[], dn: T.x_dn as string[], hd: T.hd,
  coverTitle: T.cover_h1,
};

/** Today's 8 meal pages, built from blocks. */
export function defaultMealPages(): Page[] {
  const { ways, mzWeek, exch, shop } = MEAL_DATA;
  return [
    { id: "m1", cover: true, blocks: [{ t: "sub", text: T.cover_sub }, { t: "image", src: "product" }, { t: "customer" }] },
    { id: "m2", blocks: [bar(T.bf_bar), { t: "sub", text: T.bf_sub }, { t: "slotCards", slot: "bf", style: "cards" }, text(`<p>${T.bf_note}</p>`)] },
    { id: "m3", blocks: [text(ul(T.lu_ul.map((x: string) => `<b>${x}</b>`))), { t: "rotation", slots: ["lu", "di"] }] },
    { id: "m4", blocks: [bar(T.mz_bars[0]), { t: "dose" }, { t: "cards", style: "ways", items: ways.map(([icon, a, b]) => ({ icon, lines: [a, b] })) },
      bar(T.mz_bars[1]), { t: "mzWeek", rows: [...mzWeek] }, text(`<p>${T.mz_note}</p>`)] },
    { id: "m5", blocks: [bar(T.sn_bars[0]), { t: "slotCards", slot: "s1", style: "tiles" }, bar(T.sn_bars[1]),
      { t: "table", head: [...T.exch_head], rows: exch.map((r) => [...r]) }, bar(T.sn_bars[2]), text(ul(T.sn_ul))] },
    { id: "m6", blocks: [bar(T.dr_bars[0]), { t: "cards", style: "tiles", items: T.pills.map((p: string, i: number) => ({ icon: ["🥛", "🧃", "🍓", "🥤", "🥛"][i], lines: [p] })) },
      text(ul(T.dr_ul)), bar(T.dr_bars[1]), { t: "table", head: [], rows: T.rules.map((r: string[]) => [...r]) }] },
    { id: "m7", blocks: [bar(T.shop_bar), { t: "cols", a: col(shop[0]), b: col(shop[1]) }] },
    { id: "m8", blocks: [bar(T.tr_bars[0]), { t: "cols", a: col([T.tr_cols[0]]), b: col([T.tr_cols[1]]) }, { t: "tracker" }, bar(T.tr_bars[1]), { t: "signoff" }, text(`<p>${T.tr_note}</p>`)] },
  ];
}

/** The workout booklet, redrawn portrait. */
export function defaultExPages(perWeek: number = 3, level: 0 | 1 | 2 = 0): Page[] {
  const week = [...T.x_week_ul];
  week[1] = "إذا تمرنتِ في يوم غير المكتوب، علّمي التمرين تحت يومه في التطبيق.";
  week[2] = week[2].replace("${lv.rest}", LV[level].rest);
  const pts = (a: string[][]) => ({ t: "points" as const, items: a.map(([badge, html]) => ({ badge, html: html.replace("${days}", String(perWeek)) })) });
  return [
    { id: "x1", solid: true, blocks: [{ t: "bar", text: T.x_h1, small: T.x_en }, { t: "customer" }] },
    { id: "x2", blocks: [bar([T.x_ttl[0]]), pts(T.x_intro)] },
    { id: "x3", blocks: [bar([T.x_ttl[1]]), { t: "exWeek" }, text(ul(week))] },
    { id: "x4", blocks: [bar([T.x_ttl[2]]), pts(T.x_warm)] },
    { id: "x5", blocks: [{ t: "exDays" }] },
    { id: "x6", blocks: [bar([T.x_ttl[3]]), { t: "exLog" }, text(`<p>${T.x_log_note}</p>`)] },
  ];
}

export const PLACE_NAME = { home: "منزلي", gym: "نادي" } as const;
export const LEVEL_NAME: string[] = T.x_levels;

export function seedTemplates(): Omit<Template, "id" | "created_at">[] {
  const vars = { dt: "", hd: T.hd };
  const out: Omit<Template, "id" | "created_at">[] = [
    { type: "meal", track: "gain", name: "خطة مزيونة الأساسية", cycle_len: 7, body: { slots: defaultMealSlots(), pages: defaultMealPages(), vars: { ...vars, title: T.cover_h1 } } },
  ];
  for (const place of ["home", "gym"] as const)
    for (const level of [0, 1, 2] as const)
      for (const n of [3, 4] as const)
        out.push({ type: "exercise", track: "gain", name: `${PLACE_NAME[place]}، ${LEVEL_NAME[level]}، ${n} أيام`, cycle_len: 7,
          body: { days: generateExDays(place, level, n), pages: defaultExPages(n, level), vars: { ...vars }, place, level } });
  return out;
}
